Review this YDB Go service. It creates one Query Service session at startup
and reuses it for every request so that session creation is not repeated.

```go
type Service struct {
    session query.Session
}

func NewService(ctx context.Context, db *ydb.Driver) (*Service, error) {
    s, err := db.Query().CreateSession(ctx)
    if err != nil { return nil, err }
    return &Service{session: s}, nil
}

func (s *Service) Load(ctx context.Context, id uint64) error {
    res, err := s.session.Query(ctx, "SELECT value FROM items WHERE id = $id")
    if err != nil { return err }
    return res.Close(ctx)
}
```
